#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Run it with: npm run setup:hosted
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Everything is relative to the repository root, whatever directory this is run from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."

TOTAL_STAGES=8
# Hosted values live in their own file, never in .env: .env is read by the local
# scripts and tests, which must keep using the local Supabase.
ENV_FILE=".env.hosted"
BREVO_API="https://api.brevo.com/v3"

# ── Helpers for this wizard (the library above is left alone) ─────────────

# copy_to_clipboard VALUE puts a value on the clipboard without printing it.
copy_to_clipboard() {
  if   command -v clip.exe  >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  elif command -v pbcopy    >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy   >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip     >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}

# http_status URL HEADER VALUE prints the HTTP status of a GET that sends one
# header. The header goes to curl on stdin, so a key never shows in a process list.
http_status() {
  printf 'header = "%s: %s"\n' "$2" "$3" | curl -sS -o /dev/null -w '%{http_code}' -K - "$1" 2>/dev/null || printf '000'
}

# keep_saved KEY is true when KEY is already in .env.hosted and the human keeps it.
keep_saved() {
  local current
  current=$(_existing "$1" || true)
  [[ -n "$current" ]] || return 1
  printf -v "$1" '%s' "$current"
  confirm "$1 is already saved in $ENV_FILE. Keep it?"
}

# paste_into_render NAME copies the value of $NAME to the clipboard, ready to paste.
paste_into_render() {
  local name="$1"
  if copy_to_clipboard "${!name}"; then
    step "Click the $name field and paste (Ctrl+V). The value is on your clipboard."
    pause "Pasted? Press Enter for the next field."
  else
    step "Open $ENV_FILE in an editor, copy the value after $name= (without the quotes) and paste it into the $name field."
    pause "Pasted? Press Enter for the next field."
  fi
}

# ── Stage 1 ───────────────────────────────────────────────────────────────

banner "LIBRAS hosted setup: Supabase, Brevo, Render"

stage "Check this computer"
say "This wizard saves the hosted settings to $ENV_FILE (never committed) and the"
say "GitHub repository secrets. It creates no account for you: you sign up in each"
say "dashboard when it opens."
printf '\n'
if ! git check-ignore -q "$ENV_FILE"; then
  warn "$ENV_FILE is not ignored by git. Stopping so a secret cannot be committed."
  exit 1
fi
step "$ENV_FILE is ignored by git"
if [[ ! -d node_modules ]]; then
  warn "Dependencies are not installed. Run: npm ci   and then run this wizard again."
  exit 1
fi
step "dependencies are installed"
REPO=""
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
fi
if [[ -n "$REPO" ]]; then
  step "GitHub CLI is signed in, repository: $REPO"
else
  warn "GitHub CLI is not signed in (run: gh auth login). The GitHub secrets stage will be skipped."
fi
printf '\n'
note "Stages: 2 Supabase, 3 Brevo email, 4 database, 5 Render, 6 checks, 7 GitHub secrets, 8 APK."
pause "Press Enter to start."

# ── Stage 2 ───────────────────────────────────────────────────────────────

stage "Supabase: the database and Auth"
say "Create the hosted project that holds the database and Supabase Auth."
open_url "https://supabase.com/dashboard/new"
step "Sign in (GitHub login works). Create an organization if it asks."
step "New project: name it libras. Region: Southeast Asia (Singapore), to match Render."
step "Database password: click Generate a password, COPY it now (you cannot read it again), and keep it for a later step."
step "Plan: Free. Click Create new project and wait until it finishes (about two minutes)."
pause "Project ready?"
printf '\n'
step "Look at the browser address bar: https://supabase.com/dashboard/project/<id>. The project URL is https://<id>.supabase.co"
ask SUPABASE_URL "Project URL:"
SUPABASE_URL="${SUPABASE_URL%/}"
if [[ ! "$SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]]; then
  warn "That does not look like https://<id>.supabase.co. Re-run the wizard and try again."
  exit 1
fi
write_env NODE_ENV production
write_env SUPABASE_URL "$SUPABASE_URL"

printf '\n'
say "Now the API keys."
step "In the project, open Project Settings (gear icon, bottom left) > API Keys."
step "Copy the Publishable key (starts sb_publishable_)."
ask SUPABASE_PUBLISHABLE_KEY "Publishable key:"
step "On the same page, under Secret keys, reveal and copy the default key (starts sb_secret_)."
ask_secret SUPABASE_SECRET_KEY "Secret key (hidden):"
if [[ ! "$SUPABASE_PUBLISHABLE_KEY" == sb_publishable_* ]]; then warn "The publishable key should start with sb_publishable_."; fi
if [[ ! "$SUPABASE_SECRET_KEY" == sb_secret_* ]]; then warn "The secret key should start with sb_secret_."; fi
publishable_status=$(http_status "$SUPABASE_URL/auth/v1/settings" apikey "$SUPABASE_PUBLISHABLE_KEY")
secret_status=$(http_status "$SUPABASE_URL/auth/v1/admin/users?per_page=1" apikey "$SUPABASE_SECRET_KEY")
if [[ "$publishable_status" == 200 && "$secret_status" == 200 ]]; then
  step "Supabase accepted both keys"
else
  warn "Supabase answered $publishable_status (publishable) and $secret_status (secret), not 200. Check the URL and the keys."
  confirm "Save them anyway?" || exit 1
fi
write_env SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
write_env SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"

printf '\n'
say "Finally the database connection string."
if ! keep_saved DATABASE_URL; then
  step "Click the green Connect button at the top of the project."
  step "Choose the Session pooler (not Direct connection: that one needs IPv6, which Render does not have)."
  step "Copy the connection string. It contains [YOUR-PASSWORD]: leave that as it is."
  ask DATABASE_URI_TEMPLATE "Connection string:"
  ask_secret DATABASE_PASSWORD "Database password from the project creation (hidden):"
  DATABASE_URL=$(LIBRAS_URI="$DATABASE_URI_TEMPLATE" LIBRAS_PW="$DATABASE_PASSWORD" node -e '
    const uri = process.env.LIBRAS_URI;
    if (!uri.includes("[YOUR-PASSWORD]")) { console.error("That string has no [YOUR-PASSWORD] placeholder. Copy it again from the Connect dialog."); process.exit(1); }
    process.stdout.write(uri.replace("[YOUR-PASSWORD]", () => encodeURIComponent(process.env.LIBRAS_PW)));
  ')
  if ! LIBRAS_DB_URL="$DATABASE_URL" node --input-type=module -e '
    import { parseHostedDatabaseUrl } from "./apps/api/scripts/hosted-database.ts";
    parseHostedDatabaseUrl(process.env.LIBRAS_DB_URL);
  ' 2>/dev/null; then
    warn "That is not a usable hosted connection string. Re-run the wizard and try again."
    exit 1
  fi
  write_env DATABASE_URL "$DATABASE_URL"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────

stage "Brevo: the email service"
say "Brevo sends the verification and Hold-ready emails over HTTPS (Render's free tier"
say "blocks SMTP). Its free plan allows 300 emails a day. You need an API key and one"
say "verified sender address."
open_url "https://app.brevo.com/"
step "Sign up or sign in. Finish its onboarding questions."
step "Add the sender: top-right menu > Senders, Domains & Dedicated IPs > Senders > Add a sender."
step "Use an address you control (for example a UMAK address; a Gmail address can land in spam). Brevo emails it a verification code: enter it."
pause "Sender verified (it shows as verified in the list)?"
printf '\n'
open_url "https://app.brevo.com/settings/keys/api"
step "Under SMTP & API > API keys, click Generate a new API key, name it libras-api, copy it (starts xkeysib-)."
ask_secret BREVO_API_KEY "Brevo API key (hidden):"
ask EMAIL_FROM_ADDRESS "The verified sender address:"
account_status=$(http_status "$BREVO_API/account" api-key "$BREVO_API_KEY")
if [[ "$account_status" == 200 ]]; then
  step "Brevo accepted the API key"
  senders=$(printf 'header = "api-key: %s"\n' "$BREVO_API_KEY" | curl -sS -K - "$BREVO_API/senders" 2>/dev/null || true)
  if printf '%s' "$senders" | grep -qiF "$EMAIL_FROM_ADDRESS"; then
    step "$EMAIL_FROM_ADDRESS is a sender in your Brevo account"
  else
    warn "$EMAIL_FROM_ADDRESS is not in your Brevo sender list. Add and verify it, or fix the address."
    confirm "Save it anyway?" || exit 1
  fi
else
  warn "Brevo answered HTTP $account_status, not 200. Check the key."
  confirm "Save it anyway?" || exit 1
fi
printf '\n'
open_url "https://app.brevo.com/security/authorised_ips"
step "Brevo can block API calls from unknown IP addresses, and Render's addresses change."
step "On Security > Authorized IPs, make sure blocking of unknown IP addresses is deactivated."
pause "Done?"
write_env BREVO_API_KEY "$BREVO_API_KEY"
write_env EMAIL_FROM_ADDRESS "$EMAIL_FROM_ADDRESS"
write_env EMAIL_FROM_NAME "LIBRAS"

# ── Stage 4 ───────────────────────────────────────────────────────────────

stage "Create the tables and the Librarian account"
say "Apply supabase/migrations to the hosted database. It shows what is pending first"
say "and asks you to type 'apply'."
printf '\n'
npm run db:migrate:hosted
printf '\n'
say "Now the Librarian who signs in to the desk page (created in Supabase Auth)."
ask SEED_LIBRARIAN_EMAIL "Librarian email:"
ask_secret SEED_LIBRARIAN_PASSWORD "Librarian password, 12+ characters (hidden):"
write_env SEED_LIBRARIAN_EMAIL "$SEED_LIBRARIAN_EMAIL"
write_env SEED_LIBRARIAN_PASSWORD "$SEED_LIBRARIAN_PASSWORD"
write_env SEED_LIBRARIAN_NAME "Librarian"
npm run seed:hosted

# ── Stage 5 ───────────────────────────────────────────────────────────────

stage "Render: the API service"
say "Render builds render.yaml from GitHub, so that file must be on the main branch there."
if [[ -n "$REPO" ]] && gh api "repos/$REPO/contents/render.yaml?ref=main" --silent >/dev/null 2>&1; then
  step "render.yaml is on $REPO main"
else
  warn "render.yaml is not on the main branch of the GitHub repository yet (or gh cannot see it)."
  say "Merge the deployment work to main and push, then run this wizard again: it keeps what you saved."
  confirm "Continue anyway?" || exit 0
fi
printf '\n'
open_url "https://dashboard.render.com/blueprint/new"
step "Sign up or sign in (GitHub login works)."
step "Connect the repository $REPO, branch main. Blueprint name: libras."
step "Render lists the settings render.yaml asks for. Fill each one as the wizard prompts:"
printf '\n'
for name in SUPABASE_URL SUPABASE_PUBLISHABLE_KEY DATABASE_URL BREVO_API_KEY EMAIL_FROM_ADDRESS; do
  paste_into_render "$name"
done
step "Click Deploy Blueprint. If Render asks for a payment method, the free plan still needs none: look for the free option."
step "Open the libras-api service. Its address is under the service name, like https://libras-api.onrender.com"
ask EXPO_PUBLIC_API_URL "Service address (https://...):"
EXPO_PUBLIC_API_URL="${EXPO_PUBLIC_API_URL%/}"
if [[ ! "$EXPO_PUBLIC_API_URL" =~ ^https://[A-Za-z0-9.-]+$ ]]; then
  warn "That should be an https:// address with no path. Re-run the wizard and try again."
  exit 1
fi
write_env EXPO_PUBLIC_API_URL "$EXPO_PUBLIC_API_URL"

# ── Stage 6 ───────────────────────────────────────────────────────────────

stage "Check the hosted API and send a real email"
say "Wait for the first deploy to finish (Render's Events tab says Live), then:"
printf '\n'
pause "Deploy is Live? Press Enter to ask the API for its health (waits up to five minutes)."
if npm run check:hosted; then
  step "The hosted API answers its health check"
else
  SKIPPED+=("Hosted API health check failed: see the Logs tab in Render, then run: npm run check:hosted")
  warn "No healthy answer. Fix it, then run: npm run check:hosted"
fi
printf '\n'
ask EMAIL_TEST_TO "Your own email address, to receive a test message:"
if npm run email:test -- "$EMAIL_TEST_TO"; then
  if confirm "Did the LIBRAS test email arrive (check spam too)?"; then
    step "A real email was delivered"
  else
    SKIPPED+=("Test email not seen: check Brevo (Transactional > Logs) and the spam folder, then run: npm run email:test -- you@example.com")
  fi
else
  SKIPPED+=("Test email was not accepted: run npm run email:test -- you@example.com after fixing the Brevo key or sender")
fi

# ── Stage 7 ───────────────────────────────────────────────────────────────

stage "GitHub secrets"
if [[ -n "$REPO" ]]; then
  say "Store the hosted settings in $REPO, so a later deployment workflow can use them."
  say "The current CI workflow does not read them yet. Values are sent to GitHub, never printed."
  if confirm "Write the GitHub secrets and variables to $REPO?"; then
    set_secret HOSTED_DATABASE_URL "$DATABASE_URL"
    set_secret SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
    set_secret SUPABASE_SECRET_KEY "$SUPABASE_SECRET_KEY"
    set_secret BREVO_API_KEY "$BREVO_API_KEY"
    set_var SUPABASE_URL "$SUPABASE_URL"
    set_var EMAIL_FROM_ADDRESS "$EMAIL_FROM_ADDRESS"
    set_var HOSTED_API_URL "$EXPO_PUBLIC_API_URL"
  else
    SKIPPED+=("GitHub secrets (HOSTED_DATABASE_URL, SUPABASE_PUBLISHABLE_KEY, SUPABASE_SECRET_KEY, BREVO_API_KEY) and variables (SUPABASE_URL, EMAIL_FROM_ADDRESS, HOSTED_API_URL)")
  fi
else
  SKIPPED+=("GitHub secrets: sign in with gh auth login and run this wizard again")
  warn "GitHub CLI is not signed in, so nothing was stored."
  pause "Press Enter to continue."
fi

# ── Stage 8 ───────────────────────────────────────────────────────────────

stage "The APK against the hosted API"
say "The app bakes the API address in at build time. This builds a release APK for"
say "$EXPO_PUBLIC_API_URL (it checks /health first). The first build takes about 25 minutes."
printf '\n'
if confirm "Build it now?"; then
  npm run build:apk:hosted -w @libras/mobile
  step "Install it: adb install -r apps/mobile/build/libras.apk, open the app and look for the health result."
else
  note "Later, run: npm run build:apk:hosted -w @libras/mobile"
  note "Then install it: adb install -r apps/mobile/build/libras.apk, open the app and look for the health result."
fi
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
